using System;using System.Drawing;using System.Drawing.Drawing2D;using System.Linq;using System.Windows.Forms;
namespace LoopPedal {
sealed class LfoDrag {public int Slot;public LfoDrag(int slot){Slot=slot;}}
static class LfoGlyph {
 public static void Draw(Graphics g,Rectangle box,int slot,PerformanceTimeline.Mod mod,bool hot,bool numbered=true){g.SmoothingMode=SmoothingMode.AntiAlias;using(var b=new SolidBrush(Skin.Panel))g.FillRectangle(b,box);Skin.Border(g,new RectangleF(box.X+.5f,box.Y+.5f,box.Width-1,box.Height-1),hot||mod.enabled?Skin.Mint:Skin.Muted,6);using(var p=new Pen(mod.enabled||hot?Skin.Mint:Skin.Muted,1.4f)){PointF previous=PointF.Empty;for(int i=0;i<=24;i++){double phase=i/24.0,v=mod.type==3?(phase<.5?1:-1):mod.type==4?phase*2-1:mod.type==1?1-4*Math.Abs(phase-.5):mod.type==2?Math.Exp(-phase*5)*2-1:mod.type==5?Math.Sin(Math.Floor(phase*5)*8.3):Math.Sin(phase*2*Math.PI);var next=new PointF(box.Left+4+i*(box.Width-8)/24f,box.Top+12+(float)(1-v)*(box.Height-19)/2);if(i>0)g.DrawLine(p,previous,next);previous=next;}}using(var f=new Font("Segoe UI",box.Width>=48?8:5.5f,FontStyle.Bold))Skin.Text(g,numbered?"LFO "+(slot+1):"LFO",f,Skin.Muted,new Rectangle(box.Left+1,box.Bottom-(box.Width>=48?15:10),box.Width-2,box.Width>=48?14:9),ContentAlignment.MiddleCenter);}
}
sealed class LfoGhost:Form {public int Slot;public PerformanceTimeline.Mod Mod;protected override bool ShowWithoutActivation{get{return true;}}protected override CreateParams CreateParams{get{var p=base.CreateParams;p.ExStyle|=0x08000000|0x80|0x20;return p;}}public LfoGhost(){FormBorderStyle=FormBorderStyle.None;ShowInTaskbar=false;Size=new Size(34,34);Opacity=.9;TopMost=true;SetStyle(ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);}protected override void OnPaint(PaintEventArgs e){LfoGlyph.Draw(e.Graphics,ClientRectangle,Slot,Mod,true);}}
sealed class LfoTile:Control {
 public Func<int> Slot;public Func<PerformanceTimeline.Mod> Mod;public bool Main;public Action Open,Pick,DragStarted;Point down;bool dragging,moved;
 public LfoTile(){Name="LfoTile";Size=new Size(32,32);Cursor=Cursors.Hand;SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.StandardDoubleClick,true);AccessibleRole=AccessibleRole.PushButton;AccessibleName="LFO — drag to a knob; double-click settings";var tip=new ToolTip();tip.SetToolTip(this,"Drag onto a knob · Double-click LFO settings");Disposed+=(s,e)=>tip.Dispose();}
 protected override void OnPaint(PaintEventArgs e){LfoGlyph.Draw(e.Graphics,ClientRectangle,Slot(),Mod(),dragging,!Main);}
 protected override void OnMouseDown(MouseEventArgs e){down=e.Location;moved=false;base.OnMouseDown(e);}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(e.Button!=MouseButtons.Left||dragging||Math.Abs(e.X-down.X)+Math.Abs(e.Y-down.Y)<8)return;dragging=true;moved=true;if(DragStarted!=null)DragStarted();Invalidate();using(var ghost=new LfoGhost{Slot=Slot(),Mod=Mod()})using(var timer=new System.Windows.Forms.Timer{Interval=16}){Action move=()=>ghost.Location=new Point(Cursor.Position.X+12,Cursor.Position.Y+12);move();ghost.Show();timer.Tick+=(s,a)=>move();timer.Start();try{DoDragDrop(new LfoDrag(Slot()),DragDropEffects.Link);}finally{timer.Stop();ghost.Close();dragging=false;Invalidate();}}}
 protected override void OnClick(EventArgs e){if(!moved&&Pick!=null)Pick();base.OnClick(e);}
 protected override void OnDoubleClick(EventArgs e){if(!dragging&&Open!=null)Open();base.OnDoubleClick(e);}
}
partial class Pedal {
 int selectedLfo;LfoTile lfoTile;Form lfoWindow;ToolStripDropDown lfoPicker;
 void InstallLfoTile(FlowLayoutPanel group){lfoTile=new LfoTile{Main=true,Slot=()=>selectedLfo,Mod=()=>Timeline.mods[selectedLfo],Open=ShowLfoSettings,Pick=ShowLfoPicker,Margin=new Padding(3,1,3,1)};group.Controls.Add(lfoTile);timer.Tick+=(s,e)=>{if(!lfoTile.IsDisposed)lfoTile.Invalidate();};}
 void AssignLfo(int slot,int target,long audio){if(target>=1000&&Port.Layer(target,audio)==null)return;Port.Prepare(target,audio);lock(loopers[0].Gate)Timeline.assign(Port,slot,target,audio);selectedLfo=slot;status.Text="LFO "+(slot+1)+" → "+TargetLabel(target,audio);if(lfoTile!=null)lfoTile.Invalidate();}
 void RegisterLfoTarget(Knob knob,int target,long audio){knob.AllowDrop=true;DragEventHandler enter=(s,e)=>{var drag=e.Data.GetData(typeof(LfoDrag)) as LfoDrag;e.Effect=drag==null?DragDropEffects.None:DragDropEffects.Link;knob.LfoHover=drag!=null;knob.Invalidate();};knob.DragEnter+=enter;knob.DragOver+=enter;knob.DragLeave+=(s,e)=>{knob.LfoHover=false;knob.Invalidate();};knob.DragDrop+=(s,e)=>{knob.LfoHover=false;knob.Invalidate();var drag=e.Data.GetData(typeof(LfoDrag)) as LfoDrag;if(drag!=null)AssignLfo(drag.Slot,target,audio);};}
 void ShowLfoPicker(){if(lfoPicker!=null&&!lfoPicker.IsDisposed){lfoPicker.Close();lfoPicker.Dispose();}var menu=new ToolStripDropDown{AutoSize=false,Size=new Size(190,210),Padding=Padding.Empty,BackColor=Skin.Ink};lfoPicker=menu;using(var path=Skin.Rounded(new RectangleF(0,0,190,210),16))menu.Region=new Region(path);var panel=new Panel{Size=new Size(188,208),BackColor=Skin.Panel};panel.Paint+=(sender,args)=>{args.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var border=new Pen(Color.FromArgb(138,157,169),1.5f))using(var edge=Skin.Rounded(new RectangleF(1,1,panel.Width-3,panel.Height-3),15))args.Graphics.DrawPath(border,edge);};for(int i=0;i<4;i++){int n=i;var tile=new LfoTile{Slot=()=>n,Mod=()=>Timeline.mods[n],Size=new Size(60,60),Location=new Point(20+(i%2)*80,14+(i/2)*80),Open=()=>{selectedLfo=n;menu.Close();ShowLfoSettings();},Pick=()=>selectedLfo=n,DragStarted=()=>menu.Close()};panel.Controls.Add(tile);}panel.Controls.Add(new Label{Text="DRAG TO A KNOB\nDOUBLE-CLICK TO EDIT",ForeColor=Skin.Muted,TextAlign=ContentAlignment.MiddleCenter,Location=new Point(4,176),Size=new Size(180,28),Font=new Font("Segoe UI",8)});menu.Items.Add(new ToolStripControlHost(panel){Margin=Padding.Empty,Padding=Padding.Empty,AutoSize=false,Size=panel.Size});menu.Show(lfoTile,new Point(lfoTile.Width/2-95,-212));}
 void ShowLfoSettings(){if(lfoPicker!=null)lfoPicker.Close();if(lfoWindow!=null&&!lfoWindow.IsDisposed){lfoWindow.Activate();return;}var form=new Form{Text="Agent Looper / LFO",ClientSize=new Size(400,524),FormBorderStyle=FormBorderStyle.None,StartPosition=FormStartPosition.CenterParent,ShowInTaskbar=false,BackColor=Skin.Panel,ForeColor=Color.WhiteSmoke,Font=Font};using(var path=Skin.Rounded(new RectangleF(0,0,400,524),20))form.Region=new Region(path);lfoWindow=form;form.Paint+=(sender,args)=>{args.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using(var border=new Pen(Color.FromArgb(138,157,169),1.5f))using(var edge=Skin.Rounded(new RectangleF(1,1,form.ClientSize.Width-3,form.ClientSize.Height-3),19))args.Graphics.DrawPath(border,edge);};bool updating=false;Func<PerformanceTimeline.Mod> current=()=>Timeline.mods[selectedLfo];var heading=new Label{Text="LFO",ForeColor=Skin.Mint,Font=new Font(Font.FontFamily,17,FontStyle.Bold),Location=new Point(18,14),Size=new Size(290,32)};form.Controls.Add(heading);var close=Btn("×",()=>form.Close());close.SetBounds(346,12,36,32);form.Controls.Add(close);
 var slot=new StudioChoice{DropDownStyle=ComboBoxStyle.DropDownList};slot.Items.AddRange(new object[]{"LFO 1","LFO 2","LFO 3","LFO 4"});var type=new StudioChoice{DropDownStyle=ComboBoxStyle.DropDownList};type.Items.AddRange(LfoMath.TYPES);var polarity=new StudioChoice{DropDownStyle=ComboBoxStyle.DropDownList};polarity.Items.AddRange(LfoMath.POLARITIES);var mode=new StudioChoice{DropDownStyle=ComboBoxStyle.DropDownList};mode.Items.AddRange(new object[]{"Tempo · beats/cycle","Free · seconds/cycle"});Control[] choices={slot,type,polarity,mode};string[] names={"SOURCE","WAVE","POLARITY","TIMING"};for(int i=0;i<4;i++){form.Controls.Add(new Label{Text=names[i],ForeColor=Skin.Muted,Location=new Point(18,62+i*36),Size=new Size(92,28),TextAlign=ContentAlignment.MiddleLeft});choices[i].SetBounds(114,62+i*36,268,28);form.Controls.Add(choices[i]);}
 var depth=new LfoSlider{Label="Depth",Format=v=>(v*100).ToString("0")+"%"};var rate=new LfoSlider{Label="Rate",Minimum=.02,Maximum=600,Logarithmic=true,Format=v=>v.ToString("0.00")+(current().mode==2?" beats / cycle":" sec / cycle")};var phase=new LfoSlider{Label="Phase",Format=v=>(v*360).ToString("0")+"°"};var sliders=new[]{depth,rate,phase};for(int i=0;i<3;i++){sliders[i].SetBounds(18,210+i*66,364,60);form.Controls.Add(sliders[i]);}var target=new Label{ForeColor=Skin.Mint,AutoEllipsis=true,Location=new Point(18,410),Size=new Size(364,32),TextAlign=ContentAlignment.MiddleLeft};form.Controls.Add(target);var enabled=(PadButton)Btn("ON",()=>{});var choose=Btn("TARGETS…",()=>{});var clear=Btn("UNLINK",()=>{});enabled.SetBounds(18,464,100,36);choose.SetBounds(128,464,124,36);clear.SetBounds(262,464,120,36);form.Controls.Add(enabled);form.Controls.Add(choose);form.Controls.Add(clear);
 Action sync=()=>{updating=true;var m=current();heading.Text="LFO "+(selectedLfo+1);slot.SelectedIndex=selectedLfo;type.SelectedIndex=m.type;polarity.SelectedIndex=m.polarity;mode.SelectedIndex=m.mode==2?0:1;depth.Value=m.depth;rate.Value=m.rate;phase.Value=m.phase;foreach(var slider in sliders)slider.Invalidate();target.Text=m.destinations()==0?"Drag an LFO square onto a knob":m.destinations()+" destinations · "+TargetLabel(m.target,m.audio);enabled.Text=m.enabled?"ON":"OFF";enabled.Lit=m.enabled;enabled.Invalidate();updating=false;};
 slot.SelectedIndexChanged+=(s,e)=>{if(updating)return;selectedLfo=slot.SelectedIndex;sync();};type.SelectedIndexChanged+=(s,e)=>{if(!updating)lock(loopers[0].Gate)current().type=type.SelectedIndex;};polarity.SelectedIndexChanged+=(s,e)=>{if(!updating)lock(loopers[0].Gate)current().polarity=polarity.SelectedIndex;};mode.SelectedIndexChanged+=(s,e)=>{if(!updating){lock(loopers[0].Gate)current().mode=mode.SelectedIndex==0?2:3;rate.Invalidate();}};depth.Changed=v=>{lock(loopers[0].Gate)current().depth=v;};rate.Changed=v=>{lock(loopers[0].Gate)current().rate=v;};phase.Changed=v=>{lock(loopers[0].Gate)current().phase=v;};enabled.Click+=(s,e)=>{lock(loopers[0].Gate){var m=current();m.enabled=!m.enabled;if(!m.enabled)Timeline.restore(Port,m);}sync();};clear.Click+=(s,e)=>{lock(loopers[0].Gate){var m=current();Timeline.restore(Port,m);m.enabled=false;m.target=-1;m.extraCount=0;}sync();};choose.Click+=(s,e)=>{var menu=NewMenu();var mod=current();for(int i=0;i<mod.destinations();i++){int index=i;Item(menu.Items,"Remove · "+TargetLabel(mod.targetAt(i),mod.audioAt(i)),()=>{lock(loopers[0].Gate)Timeline.unlink(Port,mod,index);sync();});}var add=Item(menu.Items,"Add destination");TargetItems(add.DropDownItems,(id,audio)=>{AssignLfo(selectedLfo,id,audio);sync();});menu.Show(choose,0,choose.Height);};form.KeyPreview=true;form.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Escape)form.Close();};sync();form.FormClosed+=(s,e)=>lfoWindow=null;form.Show(this);}
}
sealed class LfoSlider:Control {
 public string Label;public double Minimum=0,Maximum=1,Value;public bool Logarithmic;public Func<double,string> Format;public Action<double> Changed;
 public LfoSlider(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);Cursor=Cursors.Hand;TabStop=true;AccessibleRole=AccessibleRole.Slider;}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using(var path=Skin.Rounded(new RectangleF(0,0,Width,Height),10))using(var b=new SolidBrush(Skin.Ink))g.FillPath(b,path);Skin.Text(g,Label,Font,Skin.Muted,new Rectangle(12,5,100,22),ContentAlignment.MiddleLeft);Skin.Text(g,Format(Value),Font,Skin.Mint,new Rectangle(110,5,Width-122,22),ContentAlignment.MiddleRight);double n=Logarithmic?Math.Log(Math.Max(Minimum,Value)/Minimum)/Math.Log(Maximum/Minimum):(Value-Minimum)/(Maximum-Minimum);float x=16+(Width-32)*(float)Math.Max(0,Math.Min(1,n));using(var p=new Pen(Skin.Line,3))g.DrawLine(p,16,42,Width-16,42);using(var p=new Pen(Skin.Mint,3))g.DrawLine(p,16,42,x,42);using(var b=new SolidBrush(Skin.Mint))g.FillEllipse(b,x-6,36,12,12);}
 void SetAt(int x){double n=Math.Max(0,Math.Min(1,(x-16.0)/(Width-32)));Value=Logarithmic?Minimum*Math.Pow(Maximum/Minimum,n):Minimum+(Maximum-Minimum)*n;if(Changed!=null)Changed(Value);Invalidate();}
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Left){Capture=true;Focus();SetAt(e.X);}}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(Capture&&e.Button==MouseButtons.Left)SetAt(e.X);}
 protected override void OnMouseUp(MouseEventArgs e){Capture=false;base.OnMouseUp(e);}
 protected override void OnKeyDown(KeyEventArgs e){if(e.KeyCode==Keys.Left||e.KeyCode==Keys.Right){double n=Logarithmic?Math.Log(Value/Minimum)/Math.Log(Maximum/Minimum):(Value-Minimum)/(Maximum-Minimum);SetAt((int)(16+(Width-32)*(n+(e.KeyCode==Keys.Right?.01:-.01))));e.Handled=true;}base.OnKeyDown(e);}
}
